export const getStudentColumnValue = (s: any, colId: string): string => {
  if (!s || typeof s !== 'object') return '-';
  const toSafe = (v: any, fallback = '-'): string => {
    if (v === undefined || v === null || v === '') return fallback;
    if (typeof v === 'object') {
      if (Array.isArray(v)) return v.map(item => typeof item === 'object' ? JSON.stringify(item) : String(item)).filter(Boolean).join(', ') || fallback;
      return Object.values(v).map(item => typeof item === 'object' ? JSON.stringify(item) : String(item)).filter(Boolean).join(', ') || fallback;
    }
    const cleanStr = sanitizeIdNumber(v);
    return cleanStr || fallback;
  };

  switch (colId) {
    case 'foto': return s.foto ? 'Ada Foto' : '-';
    case 'nama': return toSafe(s.nama || s.namaLengkap || s['Nama Lengkap'] || s['Nama'] || s['NAMA']);
    case 'nisn': return sanitizeIdNumber(s.nisn || s['NISN'] || s['Nisn']) || '-';
    case 'nis': return sanitizeIdNumber(s.nis || s['NIS'] || s['Nis']) || '-';
    case 'nik': return sanitizeIdNumber(s.nik || s['NIK'] || s['Nik']) || '-';
    case 'gender': return toSafe(s.gender || s.jenisKelamin || s['Jenis Kelamin'] || s['JENIS KELAMIN']);
    case 'tempatLahir': return toSafe(s.tempatLahir || s['Tempat Lahir']);
    case 'tanggalLahir': return formatDateToDDMMYYYY(s.tanggalLahir || s['Tanggal Lahir']);
    case 'agama': return toSafe(s.agama || s['Agama'], 'Islam');
    case 'saudara': return toSafe(s.saudara !== undefined && s.saudara !== null && s.saudara !== '' ? s.saudara : s['Jumlah Saudara']);
    case 'noKK': return sanitizeIdNumber(s.noKK || s['Nomor KK'] || s['No KK']) || '-';
    case 'kelas': return toSafe(s.kelas || s['Kelas'] || s['Rombel'], 'Belum Diatur');
    case 'tanggalMasuk': return formatDateToDDMMYYYY(s.tanggalMasuk || s['Tanggal Masuk']);
    case 'tanggalDaftar': return formatDateToDDMMYYYY(s.tanggalDaftar || s['Tanggal Daftar']);
    case 'kelompokBelajar': return toSafe(s.kelompokBelajar || s['Kelompok Belajar']);
    case 'academicYear': return toSafe(s.academicYear || s['Tahun Ajaran']);
    case 'status': return toSafe(s.status || s['Status'] || s['Status Keaktifan'], 'Aktif');
    case 'sekolahAsal': return toSafe(s.sekolahAsal || s['Sekolah Asal']);
    case 'alamat': return toSafe(s.alamat || s['Alamat'] || s['Alamat Lengkap']);
    case 'rt': return toSafe(s.rt || s['RT']);
    case 'rw': return toSafe(s.rw || s['RW']);
    case 'dusun': return toSafe(s.dusun || s['Dusun'] || s['Lingkungan']);
    case 'kelurahan': return toSafe(s.kelurahan || s['Desa'] || s['Kelurahan']);
    case 'kecamatan': return toSafe(s.kecamatan || s['Kecamatan']);
    case 'kabupatenKota': return toSafe(s.kabupatenKota || s['Kabupaten'] || s['Kota']);
    case 'provinsi': return toSafe(s.provinsi || s['Provinsi']);
    case 'jarakRumah': return toSafe(s.jarakRumah !== undefined && s.jarakRumah !== null && s.jarakRumah !== '' ? s.jarakRumah : s['Jarak Rumah']);
    case 'namaAyah': return toSafe(s.namaAyah || s['Nama Ayah']);
    case 'statusAyah': return toSafe(s.statusAyah || s['Status Ayah']);
    case 'nikAyah': return sanitizeIdNumber(s.nikAyah || s['NIK Ayah']) || '-';
    case 'pekerjaanAyah': return toSafe(s.pekerjaanAyah || s['Pekerjaan Ayah']);
    case 'hpAyah': return sanitizeIdNumber(s.hpAyah || s['No HP Ayah']) || '-';
    case 'namaIbu': return toSafe(s.namaIbu || s['Nama Ibu']);
    case 'statusIbu': return toSafe(s.statusIbu || s['Status Ibu']);
    case 'nikIbu': return sanitizeIdNumber(s.nikIbu || s['NIK Ibu']) || '-';
    case 'pekerjaanIbu': return toSafe(s.pekerjaanIbu || s['Pekerjaan Ibu']);
    case 'hpIbu': return sanitizeIdNumber(s.hpIbu || s['No HP Ibu']) || '-';
    case 'ortu': return toSafe(s.ortu || s.namaAyah || s.namaIbu || s['Nama Wali']);
    case 'noHp': return sanitizeIdNumber(s.noHp || s.noHpOrangTua || s.hpAyah || s.hpIbu || s['No HP Orang Tua']) || '-';
    case 'jumlahHafalan': return s.jumlahHafalan !== undefined && s.jumlahHafalan !== null && s.jumlahHafalan !== '' ? `${toSafe(s.jumlahHafalan)} Juz` : '-';
    case 'nilaiRapor': return toSafe(s.nilaiRapor !== undefined && s.nilaiRapor !== null && s.nilaiRapor !== '' ? s.nilaiRapor : s['Nilai Rapor']);
    case 'prestasiAkademik': return toSafe(s.prestasiAkademik || s['Prestasi Akademik']);
    case 'prestasiNonAkademik': return toSafe(s.prestasiNonAkademik || s['Prestasi Non-Akademik']);
    default: return toSafe(s[colId]);
  }
};

export const extractYearFromDate = (dateStr?: string, defaultYear = new Date().getFullYear().toString()): string => {
  if (!dateStr || !dateStr.trim()) return defaultYear;
  const str = dateStr.trim();
  // YYYY-MM-DD
  if (/^\d{4}/.test(str)) {
    return str.slice(0, 4);
  }
  // DD/MM/YYYY or DD-MM-YYYY
  const parts = str.split(/[/-]/);
  if (parts.length === 3 && parts[2].length === 4) {
    return parts[2];
  }
  const match = str.match(/\b(20\d{2}|19\d{2})\b/);
  if (match) return match[1];
  return defaultYear;
};

export const getNextNisManualSuffix = (studentsList: any[], year: string, excludeId?: string): string => {
  const existingSuffixes = new Set<number>();
  studentsList.forEach(s => {
    if (excludeId && (s.id === excludeId || s.nisn === excludeId)) return;
    const nis = (s.nis || '').trim();
    if (nis.startsWith(year)) {
      const suffixPart = nis.slice(year.length);
      const num = parseInt(suffixPart, 10);
      if (!isNaN(num)) existingSuffixes.add(num);
    }
  });
  let nextNum = 1;
  while (existingSuffixes.has(nextNum)) {
    nextNum++;
  }
  return String(nextNum).padStart(3, '0');
};

