  const handleScanTeacherHarian = (scannedText: string) => {
    let matchedTeacher: any = null;
    let cleanQuery = scannedText.trim();

    // Try JSON parse first
    try {
      const data = JSON.parse(cleanQuery);
      const targetId = data.id || data.id_number || data.nip;
      if (targetId) {
        matchedTeacher = ustadzList.find(u => u.id === targetId || u.nip === targetId || (u.nama && u.nama.toLowerCase() === (data.nama || '').toLowerCase()));
      }
    } catch (e) {}

    if (!matchedTeacher) {
      const query = cleanQuery.toLowerCase();
      matchedTeacher = ustadzList.find(u => 
        (u.id && u.id.toLowerCase() === query) || 
        (u.nip && u.nip.toLowerCase() === query) || 
        (u.nama && u.nama.toLowerCase().includes(query)) ||
        (u.noHp && u.noHp.includes(query))
      );
    }

    if (matchedTeacher) {
      handleUpdateTeacherAttendance(matchedTeacher.id, { status: 'Hadir', hisoh: 1 }, attendanceDate);
      return {
        success: true,
        message: `${matchedTeacher.nama} (${matchedTeacher.jabatan || matchedTeacher.posisi || 'Guru'}) dicatat HADIR.`,
        name: matchedTeacher.nama,
        subtext: `NIP: ${matchedTeacher.nip || '-'} | Tgl: ${attendanceDate}`
      };
    } else {
      return {
        success: false,
        message: `Data guru dengan NIP/QR "${cleanQuery}" tidak ditemukan di master data.`,
        name: cleanQuery
      };
    }
  };

