  // Strict Conflict Checker: Jadwal piket HANYA bisa diinput jika guru TIDAK sedang mengajar di jam tersebut!
  const checkGuruTeachingConflict = (guruName: string, hari: string, jamKe: string, waktu?: string) => {
    if (!guruName || guruName.trim() === "" || guruName === "-" || guruName === "Ustadz Piket Harian" || guruName === "Petugas Piket") {
      return { isTeaching: false, conflictClasses: [] as Array<{ kelas: string; mapel: string; jam: string }> };
    }
    const cleanGuru = guruName.trim().toLowerCase();
    
    const conflicts = jadwal.filter((j: any) => {
      if (!j.hari || j.hari.trim().toLowerCase() !== hari.trim().toLowerCase()) return false;
      const jPengampu = (j.pengampu || "").trim().toLowerCase();
      if (!jPengampu || jPengampu !== cleanGuru) return false;
      
      // Match Jam: e.g. "Jam 1 (09:00 - 09:25)", "Jam 1", "09:00 - 09:25"
      const jJam = (j.jam || "").trim();
      const matchJamKe = jJam.includes(jamKe.trim());
      const matchWaktu = waktu && waktu.trim() !== "" ? jJam.includes(waktu.trim()) : false;
      const exactMatch = waktu ? jJam === `${jamKe} (${waktu})` : false;
      
      return matchJamKe || matchWaktu || exactMatch;
    });

    return {
      isTeaching: conflicts.length > 0,
      conflictClasses: conflicts.map((c: any) => ({
        kelas: c.kelas || "Semua Kelas",
        mapel: c.mapel || "Pelajaran",
        jam: c.jam || jamKe
      }))
    };
  };

  // Helper to get pool of free teachers for a specific day and time slot
