  // Helper for synchronizing Jadwal with Data Pelajaran (subjectsV2)
  const syncJadwalWithDataPelajaran = () => {
    const currentSubjectNames = new Set(subjectsV2.map(s => s.nama.trim().toLowerCase()));
    const newSubjectsToAdd: Array<typeof subjectsV2[0]> = [];
    let updatedJadwalCount = 0;

    const updatedJadwal = jadwal.map((j: any) => {
      let mapelName = (j.mapel || '').trim();
      let cleanedMapel = mapelName;

      // Strip legacy redundant suffixes like "(Ke-TMI-an / Umum)" if matching base name
      if (cleanedMapel.includes('(')) {
        const baseName = cleanedMapel.substring(0, cleanedMapel.indexOf('(')).trim();
        const matched = subjectsV2.find(s => s.nama.trim().toLowerCase() === baseName.toLowerCase());
        if (matched) {
          cleanedMapel = matched.nama;
        }
      }

      // Check if cleanedMapel matches any subject in subjectsV2
      const matchedSubject = subjectsV2.find(s => s.nama.trim().toLowerCase() === cleanedMapel.toLowerCase());
      const meta = getSubjectMeta(cleanedMapel, j.kategori || matchedSubject?.kategori, j.namaArab || matchedSubject?.namaArab, subjectsV2);

      if (matchedSubject) {
        cleanedMapel = matchedSubject.nama;
      } else if (cleanedMapel && !currentSubjectNames.has(cleanedMapel.toLowerCase())) {
        // Automatically add to Data Pelajaran
        currentSubjectNames.add(cleanedMapel.toLowerCase());
        newSubjectsToAdd.push({
          id: generateUniqueId('p_sync'),
          nama: cleanedMapel,
          namaArab: meta.namaArab,
          kategori: meta.kategori,
          classes: { [j.kelas || 'Kelas 1A1']: true },
          kkm: 75,
          pengampu: j.pengampu || 'Staf Pengajar',
          semester: 'Semua'
        });
      }

      if (cleanedMapel !== j.mapel || !j.kategori || !j.namaArab) {
        updatedJadwalCount++;
        return { 
          ...j, 
          mapel: cleanedMapel,
          kategori: meta.kategori,
          namaArab: meta.namaArab
        };
      }
      return j;
    });

    if (newSubjectsToAdd.length > 0) {
      setSubjectsV2(prev => [...prev, ...newSubjectsToAdd]);
    }
    if (updatedJadwalCount > 0) {
      setJadwal(updatedJadwal);
    }

    alert(`✅ Sinkronisasi Berhasil!\n\n• ${subjectsV2.length + newSubjectsToAdd.length} mata pelajaran terdaftar di Data Pelajaran.\n• ${updatedJadwal.length} slot jadwal telah diselaraskan dengan Data Pelajaran (Nama Arab & Kategori tersinkron).\n• ${newSubjectsToAdd.length} mata pelajaran baru dari Jadwal otomatis terintegrasi ke Data Pelajaran.`);
  };

