      const getFormattedGuru = (u: any) => u ? (u.gelar ? `${u.nama}, ${u.gelar}` : u.nama) : "GUS HAMAM YUSRON, S.Sy";
      const sampleGuru1 = getFormattedGuru(activeGuru[0]);
