      const wsData = [
        ["Hari", "Jam", "Mata Pelajaran", "Kelas", "Guru Pengampu"],
        ["Senin", matrixTimeSlots[0]?.jamKe ? `${matrixTimeSlots[0].jamKe} (${matrixTimeSlots[0].waktu})` : "Jam 1 (09:00 - 09:25)", sampleSubject1, selectedMatrixKelas || "Kelas 1A1", sampleGuru1],
        ["Senin", matrixTimeSlots[1]?.jamKe ? `${matrixTimeSlots[1].jamKe} (${matrixTimeSlots[1].waktu})` : "Jam 2 (09:25 - 10:05)", sampleSubject2, selectedMatrixKelas || "Kelas 1A1", sampleGuru2],
        ["Selasa", matrixTimeSlots[0]?.jamKe ? `${matrixTimeSlots[0].jamKe} (${matrixTimeSlots[0].waktu})` : "Jam 1 (09:00 - 09:25)", sampleSubject3, selectedMatrixKelas || "Kelas 1A1", sampleGuru3],
      ];

      const wb = XLSX.utils.book_new();
