  // Filter rombel classes by active academic year and deduplicate class names
  const activeYearClasses = useMemo(() => {
    const currentYear = (typeof tahunAjaranAktif === 'string' && tahunAjaranAktif.trim()) 
      ? tahunAjaranAktif.split(' ')[0] 
      : '2025/2026';
    
    const seenNames = new Set<string>();
    const uniqueClasses: typeof kelas = [];
    const safeKelas = Array.isArray(kelas) ? kelas.filter(Boolean) : [];

    // Prioritaskan entri yang spesifik tahun ajaran aktif jika ada
    const sorted = [...safeKelas].sort((a, b) => {
      const aYear = String(a?.academicYear || '').split(' ')[0];
      const bYear = String(b?.academicYear || '').split(' ')[0];
      const aMatch = aYear === currentYear ? 1 : 0;
      const bMatch = bYear === currentYear ? 1 : 0;
      return bMatch - aMatch;
    });

    for (const k of sorted) {
      if (k && k.nama) {
        const cleanName = String(k.nama).trim();
        if (cleanName && !seenNames.has(cleanName)) {
          seenNames.add(cleanName);
          const effectiveWali = (k.waliByYear && typeof k.waliByYear === 'object' && k.waliByYear[currentYear]) || k.wali || '-';
          uniqueClasses.push({ ...k, nama: cleanName, wali: effectiveWali });
        }
      }
    }

    return uniqueClasses;
  }, [kelas, tahunAjaranAktif]);

