  // Helper to extract unique identifier for student (prioritizing NIK, then NISN, then Name+TanggalLahir/ID)
  const getStudentUniqueKey = (s: SchoolStudent | any): string => {
    if (!s) return 'unknown';
    const cleanNik = String(s.nik || '').trim();
    if (cleanNik && cleanNik !== '-' && cleanNik.toLowerCase() !== 'null' && cleanNik.toLowerCase() !== 'undefined') {
      return `nik:${cleanNik}`;
    }
    const cleanNisn = String(s.nisn || '').trim();
    if (cleanNisn && cleanNisn !== '-' && cleanNisn.toLowerCase() !== 'null' && cleanNisn.toLowerCase() !== 'undefined') {
      return `nisn:${cleanNisn}`;
    }
    const cleanName = String(s.nama || '').trim().toUpperCase();
    if (cleanName) {
      return `nama:${cleanName}_${s.tanggalLahir || ''}`;
    }
    return `id:${s.id || Math.random()}`;
  };

  // Total unique santri count based on NIK / Student Identity
  const totalUniqueStudentsCount = useMemo(() => {
    const uniqueKeys = new Set<string>();
    students.forEach(s => {
      uniqueKeys.add(getStudentUniqueKey(s));
    });
    return uniqueKeys.size;
  }, [students]);

  // Derived list of unique parent/guardian names with role and student count based on unique students (by NIK)
  const parentOptionsList = useMemo(() => {
    // 1. Group / deduplicate students by unique student identifier (prioritizing NIK)
    const uniqueStudentsMap = new Map<string, SchoolStudent>();
    students.forEach(s => {
      const uKey = getStudentUniqueKey(s);
      // Prioritize active student records if multiple entries exist
      if (!uniqueStudentsMap.has(uKey) || (isStudentActiveInClass(s) && (s.status === 'Aktif' || !s.status))) {
        uniqueStudentsMap.set(uKey, s);
      }
    });

    const uniqueStudents = Array.from(uniqueStudentsMap.values());

    // 2. Map parent names to roles and unique student keys (by NIK)
    const map = new Map<string, { name: string; roles: Set<string>; studentKeys: Set<string> }>();

    uniqueStudents.forEach(s => {
      if (!s) return;
      const studentKey = getStudentUniqueKey(s);
      const toSafeStr = (val: any) => (val != null ? String(val).trim() : '');
      const candidates: Array<{ name: string; role: string }> = [
        { name: toSafeStr(s.namaAyah), role: 'Ayah' },
        { name: toSafeStr(s.namaIbu), role: 'Ibu' },
        { name: toSafeStr(s.namaWali), role: 'Wali' },
        { name: toSafeStr(s.ortu), role: 'Ortu' }
      ];

      candidates.forEach(({ name, role }) => {
        if (!name || name === '-' || name.toLowerCase() === 'null' || name.toLowerCase() === 'undefined') return;
        const key = name.toLowerCase();
        if (!map.has(key)) {
          map.set(key, { 
            name, 
            roles: new Set([role]), 
            studentKeys: new Set([studentKey]) 
          });
        } else {
          const item = map.get(key)!;
          item.roles.add(role);
          item.studentKeys.add(studentKey);
        }
      });
    });

    return Array.from(map.values())
      .map(item => ({
        name: item.name,
        roles: item.roles,
        count: item.studentKeys.size // Count of unique students by NIK
      }))
      .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), undefined, { sensitivity: 'base' }));
  }, [students]);

  // Open Parent Details Modal showing all connected students and parent info
  const handleOpenParentDetail = (parentName: any) => {
    if (!parentName) return;
    const cleanParent = String(parentName).trim().toLowerCase();
    if (cleanParent === '-' || cleanParent === 'belum diatur' || cleanParent === 'null' || cleanParent === 'undefined') return;
    
    // Find all matching students
    const matchedStudentsMap = new Map<string, SchoolStudent>();
    const roles = new Set<string>();
    let primaryPhone = '';
    let fatherNik = '';
    let motherNik = '';
    let fatherJob = '';
    let motherJob = '';
    let address = '';

    students.forEach(s => {
      if (!s) return;
      let isMatch = false;
      const sAyah = String(s.namaAyah || '').trim().toLowerCase();
      const sIbu = String(s.namaIbu || '').trim().toLowerCase();
      const sWali = String(s.namaWali || '').trim().toLowerCase();
      const sOrtu = String(s.ortu || '').trim().toLowerCase();

      if (sAyah && sAyah === cleanParent) {
        roles.add('Ayah');
        isMatch = true;
      }
      if (sIbu && sIbu === cleanParent) {
        roles.add('Ibu');
        isMatch = true;
      }
      if (sWali && sWali === cleanParent) {
        roles.add('Wali');
        isMatch = true;
      }
      if (sOrtu && sOrtu === cleanParent) {
        roles.add('Orang Tua');
        isMatch = true;
      }

      if (isMatch) {
        const uKey = getStudentUniqueKey(s);
        if (!matchedStudentsMap.has(uKey) || (isStudentActiveInClass(s) && (s.status === 'Aktif' || !s.status))) {
          matchedStudentsMap.set(uKey, s);
        }

        if (!primaryPhone) {
          primaryPhone = s.noHp || s.noHpOrangTua || s.hpAyah || s.hpIbu || '';
        }
        if (!fatherNik && s.nikAyah) fatherNik = s.nikAyah;
        if (!motherNik && s.nikIbu) motherNik = s.nikIbu;
        if (!fatherJob && s.pekerjaanAyah) fatherJob = s.pekerjaanAyah;
        if (!motherJob && s.pekerjaanIbu) motherJob = s.pekerjaanIbu;
        if (!address && s.alamat) {
          address = `${s.alamat}${s.rt ? ` RT ${s.rt}` : ''}${s.rw ? ` RW ${s.rw}` : ''}${s.kelurahan ? `, ${s.kelurahan}` : ''}${s.kecamatan ? `, ${s.kecamatan}` : ''}${s.kabupatenKota ? `, ${s.kabupatenKota}` : ''}`;
        }
      }
    });

    if (roles.size === 0) roles.add('Orang Tua');

    setSelectedParentForModal({
      name: parentName.trim(),
      roles,
      students: Array.from(matchedStudentsMap.values()),
      primaryPhone,
      fatherNik,
      motherNik,
      fatherJob,
      motherJob,
      address
    });
  };

