  // Automatic Masa Kerja calculation and NIP generation from TMT Guru
  useEffect(() => {
    if (ustadzForm.tmtGuru) {
      const start = new Date(ustadzForm.tmtGuru);
      const end = new Date();
      
      if (!isNaN(start.getTime())) {
        // Masa Kerja
        let years = end.getFullYear() - start.getFullYear();
        let months = end.getMonth() - start.getMonth();
        let days = end.getDate() - start.getDate();

        if (days < 0) {
          months -= 1;
          const prevMonth = new Date(end.getFullYear(), end.getMonth(), 0);
          days += prevMonth.getDate();
        }

        if (months < 0) {
          years -= 1;
          months += 12;
        }

        const calculated = `${years} Tahun, ${months} Bulan, ${days} Hari`;
        
        // NIP Generation: 2 digit Month + 2 digit Year + 4 digits sequence
        let nextNip = ustadzForm.nip;
        if (!ustadzForm.nip && !editingUstadzObj) {
          const mm = String(start.getMonth() + 1).padStart(2, '0');
          const yy = String(start.getFullYear()).slice(-2);
          const prefix = mm + yy;
          
          let maxSeq = 0;
          ustadzList.forEach(u => {
            if (u.nip && u.nip.length >= 4) {
              const seqStr = u.nip.slice(-4);
              const seq = parseInt(seqStr, 10);
              if (!isNaN(seq) && seq > maxSeq) {
                maxSeq = seq;
              }
            }
          });
          const nextSeq = String(maxSeq + 1).padStart(4, '0');
          nextNip = prefix + nextSeq;
        }

        // Only update if changes detected
        if (calculated !== ustadzForm.masaKerja || nextNip !== ustadzForm.nip) {
          setUstadzForm(prev => ({ 
            ...prev, 
            masaKerja: calculated,
            nip: nextNip
          }));
        }
      }
    }
  }, [ustadzForm.tmtGuru, ustadzList, editingUstadzObj]);

