  // --- ACTIONS ---

  const handleUpdateStudentAttendance = (studentId: string, status: 'Hadir' | 'Izin' | 'Sakit' | 'Alpa', dateVal: string) => {
    // 1. Update real date-based array state without marking isSubmitted = true
    // Status card rombel remains unsubmitted (Red/Belum) until "Simpan & Kirim" button is clicked
    setStudentAttendanceV2(prev => {
      const existingIdx = prev.findIndex(item => item.studentId === studentId && item.tanggal === dateVal);
      if (existingIdx > -1) {
        const copy = [...prev];
        copy[existingIdx] = {
          ...copy[existingIdx],
          status,
          academicYear: tahunAjaranAktif,
          isSubmitted: false
        };
        return copy;
      } else {
        return [
          ...prev,
          {
            id: generateUniqueId('sa'),
            studentId,
            tanggal: dateVal,
            status,
            academicYear: tahunAjaranAktif,
            isSubmitted: false
          }
        ];
      }
    });

    // Reset submitted rombel state so card is red/belum until saved
    if (selectedClass) {
      const rombelKey = `${dateVal}_${selectedClass}_${tahunAjaranAktif}`;
      setSubmittedRombels(prev => {
        if (prev[rombelKey]) {
          const next = { ...prev };
          delete next[rombelKey];
          localStorage.setItem('db_attendance_submitted_rombels', JSON.stringify(next));
          return next;
        }
        return prev;
      });
    }

    // 2. Update fallback local legacy map for backward compatibility if needed
    setStudentAttendance(prev => ({
      ...prev,
      [`${selectedClass}_${selectedSubject}_${studentId}`]: status
    }));
  };

  const handleUpdateTeacherAttendance = (teacherId: string, fields: Partial<{ status: 'Hadir' | 'Izin' | 'Sakit' | 'Alpa' | 'Belum', hisoh: number, keterangan: string }>, dateVal: string) => {
    setTeacherAttendanceHistory(prev => {
      const matchIdx = prev.findIndex(h => h.teacherId === teacherId && h.tanggal === dateVal);
      let updated: typeof prev;
      if (matchIdx > -1) {
        const copy = [...prev];
        copy[matchIdx] = {
          ...copy[matchIdx],
          ...fields,
          academicYear: tahunAjaranAktif
        };
        // Deduplicate: ensure only 1 single record exists for this teacher on this date
        updated = copy.filter((h, idx) => idx === matchIdx || !(h.teacherId === teacherId && h.tanggal === dateVal));
      } else {
        const cleaned = prev.filter(h => !(h.teacherId === teacherId && h.tanggal === dateVal));
        updated = [
          ...cleaned,
          {
            id: generateUniqueId('ta'),
            teacherId: teacherId,
            tanggal: dateVal,
            status: fields.status || 'Belum',
            hisoh: fields.hisoh !== undefined ? fields.hisoh : (fields.status === 'Hadir' ? 1 : 0),
            keterangan: fields.keterangan || '',
            academicYear: tahunAjaranAktif
          }
        ];
      }
      localStorage.setItem('db_teachers_attendance_history', JSON.stringify(updated));
      return updated;
    });
  };

  const executeBarcodeScan = (e?: React.FormEvent) => {
  if (!isPageWritable("akademik_barcode")) { alert("Mode Read-Only: Pencatatan presensi barcode dinonaktifkan."); return; }
    if (e) e.preventDefault();
    const input = manualBarcode.trim();
    if (!input) return;

    const today = new Date().toISOString().split('T')[0];

    // Search student by NISN or name
    const foundS = students.find(s => s.nisn === input || s.nama.toLowerCase() === input.toLowerCase());
    // Search teacher by NIP or name
    const foundT = ustadzList.find(u => u.nip === input || u.nama.toLowerCase() === input.toLowerCase());
    
    if (foundS) {
      setScanFlash(true);
      setTimeout(() => setScanFlash(false), 800);
      
      handleUpdateStudentAttendance(foundS.id, 'Hadir', today);

      const exists = scannedLogs.find(l => l.nisn === (foundS.nisn || foundS.id));
      setScannedLogs(prev => [
        {
          nisn: foundS.nisn || foundS.id,
          nama: foundS.nama,
          kelas: foundS.kelas || 'Siswa',
          waktu: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          tipe: exists ? 'RE-ENTERED' : 'BERHASIL'
        },
        ...prev
      ]);
      setManualBarcode('');
    } else if (foundT) {
      setScanFlash(true);
      setTimeout(() => setScanFlash(false), 800);

      handleUpdateTeacherAttendance(foundT.id, { status: 'Hadir', hisoh: 1 }, today);

      const exists = scannedLogs.find(l => l.nisn === (foundT.nip || foundT.id));
      setScannedLogs(prev => [
        {
          nisn: foundT.nip || foundT.id,
          nama: `[USTADZ] ${foundT.nama}`,
          kelas: foundT.jabatan || 'Guru',
          waktu: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
          tipe: exists ? 'RE-ENTERED' : 'BERHASIL'
        },
        ...prev
      ]);
      setManualBarcode('');
    } else {
      alert('Kartu NISN / Barcode tidak dikenali di Database Master!');
    }
  };

  const handleQRScan = (decodedText: string) => {
    try {
      // Try to parse as JSON first (our own generated QR)
      const data = JSON.parse(decodedText);
      if (data.id && data.type) {
        setScanFlash(true);
        setTimeout(() => setScanFlash(false), 800);
        const today = new Date().toISOString().split('T')[0];

        if (data.type === 'STUDENT') {
          const found = students.find(s => s.id === data.id);
          if (found) {
            handleUpdateStudentAttendance(found.id, 'Hadir', today);
            
            // Log for Terminal UI
            const exists = scannedLogs.find(l => l.nisn === (found.nisn || found.id));
            setScannedLogs(prev => [
              {
                nisn: found.nisn || found.id,
                nama: found.nama,
                kelas: found.kelas || 'Belum Diatur',
                waktu: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
                tipe: exists ? 'RE-ENTERED' : 'BERHASIL'
              },
              ...prev
            ]);
          }
        } else if (data.type === 'TEACHER') {
          const found = ustadzList.find(u => u.id === data.id);
          if (found) {
            handleUpdateTeacherAttendance(found.id, { status: 'Hadir', hisoh: 1 }, today);
            
            // Log for Terminal UI
            const exists = scannedLogs.find(l => l.nisn === (found.nip || found.id));
            setScannedLogs(prev => [
              {
                nisn: found.nip || found.id,
                nama: `[USTADZ] ${found.nama}`,
                kelas: found.jabatan || 'Guru',
                waktu: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
                tipe: exists ? 'RE-ENTERED' : 'BERHASIL'
              },
              ...prev
            ]);
          }
        }
      } else {
        // Fallback for raw text
        setManualBarcode(decodedText);
        executeBarcodeScan();
      }
    } catch (e) {
      // If parsing fails, maybe it's a raw NISN or NIP
      setManualBarcode(decodedText);
      executeBarcodeScan();
    }
  };

  const startScanner = () => {
    setIsScanning(true);
    setTimeout(() => {
      const scanner = new Html5QrcodeScanner(
        "qr-reader", 
        { 
          fps: 20, 
          qrbox: (viewfinderWidth, viewfinderHeight) => {
            const minEdge = Math.min(viewfinderWidth, viewfinderHeight);
            const size = Math.floor(minEdge * 0.7);
            return { width: size, height: size };
          },
          aspectRatio: 1.0,
          rememberLastUsedCamera: true,
          supportedScanTypes: [0], // 0 = SCAN_TYPE_CAMERA
          showTorchButtonIfSupported: true,
          showZoomSliderIfSupported: true,
          defaultZoomValueIfSupported: 1.5
        },
        /* verbose= */ false
      );
      
      scanner.render((decodedText) => {
        handleQRScan(decodedText);
      }, (error) => {
        // silent error for frame scanning
      });
      
      scannerRef.current = scanner;
    }, 500);
  };

  const stopScanner = () => {
    if (scannerRef.current) {
      scannerRef.current.clear().catch(err => console.error("Failed to clear scanner", err));
      scannerRef.current = null;
    }
    setIsScanning(false);
  };

  useEffect(() => {
    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
      }
    };
  }, []);

  useEffect(() => {
    if (activeMenu !== 'akademik_barcode') {
      stopScanner();
    }
  }, [activeMenu]);

  const handleUpdateGrade = (studentId: string, type: 'tugas' | 'uts' | 'uas', value: number) => {
    const val = isNaN(value) ? 0 : Math.min(100, Math.max(0, value));
    setGrades(prev => ({
      ...prev,
      [studentId]: {
        ...prev[studentId],
        [type]: val
      }
    }));
  };

  const handleUpdateKarakter = (studentId: string, field: string, value: any) => {
  if (!isPageWritable("akademik_nilai")) return;
    const year = gradeInputTahun || tahunAjaranAktif;
    const sem = gradeInputSemester || semesterAktif;
    
    setGradesKarakterV2(prev => {
      const idx = prev.findIndex(g => g.studentId === studentId && g.academicYear === year && g.semester === sem);
      if (idx > -1) {
        const updated = [...prev];
        updated[idx] = {
          ...updated[idx],
          [field]: value
        };
        return updated;
      } else {
        const newItem = {
          id: generateUniqueId('gk'),
          studentId,
          academicYear: year,
          semester: sem,
          akhlak: '8',
          kerajinan: '8',
          kebersihan: '8',
          sakit: 0,
          izin: 0,
          alpa: 0,
          hafalanJuz: 0,
          [field]: value
        };
        return [...prev, newItem];
      }
    });
  };

