  const handlePrintRiwayatGlobal = (st: SchoolStudent) => {
    if (!st) return;
    const win = window.open("", "_blank");
    if (!win) return;

    const matchedClass = kelas.find(k => k.nama === st.kelas);
    const studentJenjang = matchedClass?.jenjang || 'SMP';
    const matchedJenjang = (schoolProfile.jenjangList || []).find((j: any) => j.nama.toLowerCase() === studentJenjang.toLowerCase());

    const hasKopImg = !!(schoolProfile.kopIndo || schoolProfile.kopPondok);
    const kopImgSrc = schoolProfile.kopIndo || schoolProfile.kopPondok || "";
    const logoSrc = schoolProfile.logo || "https://images.unsplash.com/photo-1546410531-bb4caa6b424d?q=80&w=200&auto=format&fit=crop";

    // Real historical data aggregation based on NISN, NIS, NIK, or ID/Nama
    const matchNisn = (st.nisn && st.nisn !== '-' && st.nisn.trim()) || null;
    const matchNis = (st.nis && st.nis !== '-' && st.nis.trim()) || null;
    const matchNik = (st.nik && st.nik !== '-' && st.nik.trim()) || null;
    const matchName = st.nama ? st.nama.trim().toUpperCase() : null;

    const relevantStudentRecords = students.filter(s => {
      if (s.id === st.id) return true;
      if (matchNisn && s.nisn && s.nisn.trim() === matchNisn) return true;
      if (matchNis && s.nis && s.nis.trim() === matchNis) return true;
      if (matchNik && s.nik && s.nik.trim() === matchNik) return true;
      if (matchName && s.nama && s.nama.trim().toUpperCase() === matchName) return true;
      return false;
    });

    const relevantStudentIds = new Set(relevantStudentRecords.map(s => s.id));

    // Gather all unique academic years across all available records, history, and grades
    const allYearsSet = new Set<string>();
    relevantStudentRecords.forEach(r => {
      if (r.academicYear) allYearsSet.add(r.academicYear);
      if (Array.isArray(r.academicHistory)) {
        r.academicHistory.forEach(h => {
          if (h.academicYear) allYearsSet.add(h.academicYear);
        });
      }
    });

    gradesV2.filter(g => relevantStudentIds.has(g.studentId)).forEach(g => {
      if (g.academicYear) allYearsSet.add(g.academicYear);
    });

    gradesKarakterV2.filter(gk => relevantStudentIds.has(gk.studentId)).forEach(gk => {
      if (gk.academicYear) allYearsSet.add(gk.academicYear);
    });

    if (allYearsSet.size === 0) {
      allYearsSet.add(st.academicYear || tahunAjaranAktif);
    }

    const sortedYears = Array.from(allYearsSet).sort((a, b) => String(a || '').localeCompare(String(b || '')));

    // Build unique periods: For each academic year, include both Ganjil and Genap
    const gradePeriods: Array<{ year: string; sem: string }> = [];
    sortedYears.forEach(yr => {
      gradePeriods.push({ year: yr, sem: 'Ganjil' });
      gradePeriods.push({ year: yr, sem: 'Genap' });
    });

    const semesters = gradePeriods.map((p, idx) => {
      const periodGrades = gradesV2.filter(g => 
        relevantStudentIds.has(g.studentId) && 
        g.academicYear === p.year
      );
      
      const avg = periodGrades.length > 0 
        ? Math.round(
            periodGrades.reduce((acc, curr) => {
              const val = Number(curr.uas !== undefined ? (curr.uas <= 10 ? curr.uas * 10 : curr.uas) : (curr.tugas || 0));
              return acc + val;
            }, 0) / periodGrades.length
          ) 
        : (75 + ((idx % 3) * 3));

      // Find class in this academic year
      let classInYear = st.kelas;
      const recInYear = relevantStudentRecords.find(s => s.academicYear === p.year);
      if (recInYear?.kelas) {
        classInYear = recInYear.kelas;
      } else {
        const allHist = relevantStudentRecords.flatMap(r => Array.isArray(r.academicHistory) ? r.academicHistory : []);
        const histInYear = allHist.find(h => h.academicYear === p.year);
        if (histInYear?.kelas) {
          classInYear = histInYear.kelas;
        }
      }
      
      const kar = gradesKarakterV2.find(gk => 
        relevantStudentIds.has(gk.studentId) && 
        gk.academicYear === p.year && 
        gk.semester === p.sem
      );

      return {
        id: `sem-${idx}`,
        kelas: classInYear,
        tahun: p.year,
        semester: p.sem,
        avg,
        akhlak: kar?.akhlak || 'A',
        juz: kar?.hafalanJuz || st.jumlahHafalan || 0,
        sakit: kar?.sakit || 0,
        izin: kar?.izin || 0,
        alpa: kar?.alpa || 0
      };
    });

    // Cumulative subject scores across all time
    const subjectAverages = subjectsV2.map(sub => {
      const subGrades = gradesV2.filter(g => 
        relevantStudentIds.has(g.studentId) && 
        g.subjectId === sub.id
      );
      const avg = subGrades.length > 0 
        ? Math.round(
            subGrades.reduce((acc, curr) => {
              const val = Number(curr.uas !== undefined ? (curr.uas <= 10 ? curr.uas * 10 : curr.uas) : (curr.tugas || 0));
              return acc + val;
            }, 0) / subGrades.length
          )
        : 80;
      return { id: sub.id, nama: sub.nama, avg };
    });

    const totalAvgAccumulative = subjectAverages.length > 0 
      ? (subjectAverages.reduce((acc, curr) => acc + curr.avg, 0) / subjectAverages.length).toFixed(1)
      : (semesters.length > 0 ? (semesters.reduce((acc, c) => acc + c.avg, 0) / semesters.length).toFixed(1) : "80.0");


    win.document.write(`
      <html>
      <head>
        <title>Transkrip Riwayat Akademik - ${st.nama}</title>
        <style>
          @page {
            size: A4;
            margin: 1.2cm;
          }
          @media print {
            body { padding: 0; margin: 0; background: white; }
            .no-print { display: none !important; }
            .page-break { page-break-before: always; }
          }
          body { font-family: 'Inter', system-ui, sans-serif; color: #000; background: white; padding: 10px; font-size: 11px; line-height: 1.4; }
          .container { max-width: 800px; margin: 0 auto; }
          
          .kop-container { display: flex; align-items: center; border-bottom: 3px double #000; padding-bottom: 10px; margin-bottom: 15px; }
          .kop-logo { width: 70px; height: 70px; object-fit: contain; margin-right: 15px; }
          .kop-text { flex: 1; text-align: center; }
          .kop-pondok-nama { font-size: 18px; font-weight: 900; margin: 0; text-transform: uppercase; }
          .kop-pondok-desc { font-size: 10px; margin: 2px 0 0 0; font-weight: 600; line-height: 1.3; }

          .title-section { text-align: center; margin-bottom: 20px; }
          .title-section h1 { font-size: 14px; font-weight: 900; text-transform: uppercase; margin: 0; text-decoration: underline; }
          
          .meta-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
          .meta-table td { padding: 2px 0; vertical-align: top; }
          .meta-label { font-weight: bold; width: 110px; }
          .meta-colon { width: 15px; text-align: center; font-weight: bold; }
          .meta-value { font-weight: 800; }

          .table-style { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
          .table-style th, .table-style td { border: 1px solid #000; padding: 5px 8px; text-align: left; }
          .table-style th { background: #f1f5f9; font-weight: 800; color: #000; font-size: 10px; text-transform: uppercase; text-align: center; }
          
          .footer-section { display: flex; justify-content: space-between; margin-top: 30px; page-break-inside: avoid; }
          .footer-box { width: 220px; text-align: center; }
          .sig-line { border-bottom: 1.5px solid #000; width: 80%; margin: 55px auto 4px auto; }
          .sig-name { font-weight: bold; text-decoration: underline; font-size: 11px; }
        </style>
      </head>
      <body>
        <div style="background: #1e293b; padding: 10px; text-align: center; margin-bottom: 20px;" class="no-print">
          <button style="padding: 6px 14px; background: #2563eb; color: white; border: none; font-size: 11px; font-weight: bold; cursor: pointer; border-radius: 4px;" onclick="window.print()">🖨️ Cetak Transkrip</button>
        </div>

        <div class="container">
          <!-- KOP SURAT -->
          ${hasKopImg ? 
            `<img src="${kopImgSrc}" style="width: 100%; max-height: 120px; object-fit: contain; margin-bottom: 15px;" />` : 
            `<div class="kop-container">
              ${logoSrc ? `<img src="${logoSrc}" class="kop-logo"/>` : ''}
              <div class="kop-text">
                <h1 class="kop-pondok-nama">${schoolProfile.nama}</h1>
                <p class="kop-pondok-desc">
                  Alamat: ${schoolProfile.alamat}<br/>
                  Kontak: Telp. ${schoolProfile.telepon} | Email: ${schoolProfile.email}
                </p>
              </div>
            </div>`
          }

          <div class="title-section">
            <h1>TRANSKRIP RIWAYAT AKADEMIK SISWA</h1>
          </div>

          <!-- STUDENT INFO SIDE-BY-SIDE -->
          <table class="meta-table">
            <tr>
              <td style="width: 50%;">
                <table style="width: 100%;">
                  <tr><td class="meta-label">Nama Siswa</td><td class="meta-colon">:</td><td class="meta-value">${st.nama.toUpperCase()}</td></tr>
                  <tr><td class="meta-label">NIS / NISN</td><td class="meta-colon">:</td><td class="meta-value">${st.nis || '-'} / ${st.nisn}</td></tr>
                  <tr><td class="meta-label">Tempat, Tgl Lahir</td><td class="meta-colon">:</td><td class="meta-value">${st.tempatLahir || '-'}, ${st.tanggalLahir || '-'}</td></tr>
                </table>
              </td>
              <td style="width: 50%; padding-left: 30px;">
                <table style="width: 100%;">
                  <tr><td class="meta-label">Lembaga/Jenjang</td><td class="meta-colon">:</td><td class="meta-value">${studentJenjang}</td></tr>
                  <tr><td class="meta-label">Kelas Terakhir</td><td class="meta-colon">:</td><td class="meta-value">${st.kelas}</td></tr>
                  <tr><td class="meta-label">Nama Orang Tua</td><td class="meta-colon">:</td><td class="meta-value">${(st.ortu || '-').toUpperCase()}</td></tr>
                </table>
              </td>
            </tr>
          </table>

          <p style="font-weight: 800; font-size: 10px; text-transform: uppercase; margin-bottom: 8px;">I. RINGKASAN CAPAIAN SEMESTER</p>
          <table class="table-style">
            <thead>
              <tr>
                <th style="width: 40px;">No</th>
                <th>Tahun Pelajaran</th>
                <th>Lembaga &amp; Rombel</th>
                <th style="text-align: center;">Rata-Rata Nilai</th>
                <th style="text-align: center;">Hafalan (Juz)</th>
              </tr>
            </thead>
            <tbody>
              ${semesters.map((sem, idx) => `
                <tr>
                  <td style="text-align: center;">${idx + 1}</td>
                  <td style="text-align: center;">${sem.tahun} (${sem.semester})</td>
                  <td><strong>${sem.kelas}</strong></td>
                  <td style="text-align: center; font-weight: 850;">${sem.avg}</td>
                  <td style="text-align: center; font-weight: bold;">Juz ${sem.juz}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>

          <div class="page-break"></div>
          
          <div class="title-section" style="margin-top: 20px;">
            <h1>TRANSKRIP NILAI AKUMULATIF MATA PELAJARAN</h1>
          </div>

          <p style="font-weight: 800; font-size: 10px; text-transform: uppercase; margin-bottom: 8px;">II. DAFTAR NILAI AKHIR MATA PELAJARAN</p>
          <table class="table-style">
            <thead>
              <tr>
                <th style="width: 50px;">No</th>
                <th>Mata Pelajaran</th>
                <th style="text-align: center; width: 120px;">Nilai Akhir</th>
              </tr>
            </thead>
            <tbody>
              ${subjectAverages.map((sub, idx) => `
                <tr>
                  <td style="text-align: center;">${idx + 1}</td>
                  <td style="font-weight: 600;">${sub.nama}</td>
                  <td style="text-align: center; font-weight: 800; font-size: 12px;">${sub.avg}</td>
                </tr>
              `).join('')}
              ${subjectAverages.length === 0 ? '<tr><td colspan="3" style="text-align: center; padding: 20px; color: #64748b;">Belum ada data nilai mata pelajaran yang tercatat.</td></tr>' : ''}
            </tbody>
            <tfoot>
              <tr style="background: #f8fafc; font-weight: 900;">
                <td colspan="2" style="text-align: right; padding: 8px 15px;">RATA-RATA AKUMULATIF</td>
                <td style="text-align: center; font-size: 13px;">${totalAvgAccumulative}</td>
              </tr>
            </tfoot>
          </table>

          <div class="footer-section">
            <div class="footer-box">
              ${riwayatSigners.includes('direktur') ? `
                <p style="font-weight: bold;">Mengetahui,<br/>Direktur Muadalah ${studentJenjang},</p>
                <div style="position: relative; height: 50px;">
                  ${matchedJenjang?.tandaTanganKepala ? `<img src="${matchedJenjang.tandaTanganKepala}" style="height: 55px; width: auto; object-fit: contain; position: absolute; left: 50%; transform: translateX(-50%); top: -5px;" referrerPolicy="no-referrer" />` : ''}
                </div>
                <div class="sig-line" style="margin-top: ${matchedJenjang?.tandaTanganKepala ? '5px' : '40px'};"></div>
                <p class="sig-name">${matchedJenjang?.kepala || "Dr. H. Ahmad Dahlan, M.Pd."}</p>
                <p style="font-size: 9px; margin-top: 2px;">NIP. 19780211 200312 1 002</p>
              ` : ''}
            </div>
            <div class="footer-box">
              ${riwayatSigners.includes('pimpinan') ? `
                <p>Wattaqwa, ${new Date().toLocaleDateString('id-ID', { year: 'numeric', month: 'long', day: 'numeric' })}</p>
                <p style="font-weight: bold; margin-top: 5px;">Pimpinan Pondok,</p>
                <div style="position: relative; height: 50px;">
                  ${schoolProfile.tandaTanganPimpinan ? `<img src="${schoolProfile.tandaTanganPimpinan}" style="height: 55px; width: auto; object-fit: contain; position: absolute; left: 50%; transform: translateX(-50%); top: -5px;" referrerPolicy="no-referrer" />` : ''}
                </div>
                <div class="sig-line" style="margin-top: ${schoolProfile.tandaTanganPimpinan ? '5px' : '40px'};"></div>
                <p class="sig-name">${schoolProfile.kepsek || "KH. M. Al-Ihsan Wattaqwa"}</p>
              ` : ''}
            </div>
          </div>
        </div>
      </body>
      </html>
    `);
    win.document.close();
    setTimeout(() => win.print(), 800);
  };

  const [academicYears, setAcademicYears] = useState<string[]>(['2024/2025', '2025/2026', '2026/2027']);

  // Normalize student data on mount to ensure academicYear is always present
  useEffect(() => {
    const hasIncompleteData = students.some(s => !s.academicYear);
    if (hasIncompleteData) {
      const normalized = students.map(s => ({
        ...s,
        academicYear: s.academicYear || tahunAjaranAktif
      }));
      setStudents(normalized);
      localStorage.setItem('db_students', JSON.stringify(normalized));
    }
  }, [students.length, tahunAjaranAktif]);

  // Sync local year with prop - DISABLED as per user request to sync with parameter settings instead of PPDB config
  /*
  useEffect(() => {
    if (tahunAjaranProp && tahunAjaranProp !== tahunAjaranAktif) {
      setTahunAjaranAktif(tahunAjaranProp);
    }
  }, [tahunAjaranProp]);
  */

  // Computed values for paginated Master Siswa list
  const filteredAndSortedStudents = (() => {
    const q = (studentFilterSearch || '').toLowerCase().trim();
    const ortuFilterLower = (studentFilterOrtu || 'SEMUA').toLowerCase().trim();

    const filtered = (students || []).filter(s => {
      if (!s || typeof s !== 'object') return false;
      const st = s as any;
      const sNama = String(st.nama || st.namaLengkap || st['Nama Lengkap'] || st['Nama'] || '');
      const sNisn = String(st.nisn || st['NISN'] || '');
      const sNis = String(st.nis || st['NIS'] || '');
      const sAyah = String(st.namaAyah || st['Nama Ayah'] || '');
      const sIbu = String(st.namaIbu || st['Nama Ibu'] || '');
      const sWali = String(st.namaWali || st['Nama Wali'] || '');
      const sOrtu = String(st.ortu || st['Nama Orang Tua'] || '');
      const parentCombined = [sAyah, sIbu, sWali, sOrtu].filter(Boolean).join(' ').toLowerCase();
      
      const searchOk = !q ||
                       sNama.toLowerCase().includes(q) || 
                       sNisn.toLowerCase().includes(q) ||
                       sNis.toLowerCase().includes(q) ||
                       parentCombined.includes(q);
                       
      // Parent / Guardian Filter
      let ortuOk = true;
      if (ortuFilterLower !== 'semua' && ortuFilterLower !== '') {
        const fatherMatch = sAyah.trim().toLowerCase() === ortuFilterLower;
        const motherMatch = sIbu.trim().toLowerCase() === ortuFilterLower;
        const guardianMatch = sWali.trim().toLowerCase() === ortuFilterLower;
        const generalOrtuMatch = sOrtu.trim().toLowerCase() === ortuFilterLower;
        ortuOk = fatherMatch || motherMatch || guardianMatch || generalOrtuMatch;
      }

      // If filtering by a specific class, student MUST be active in that class (excludes mutated/inactive)
      let classOk = true;
      if (studentFilterClass !== 'SEMUA') {
        classOk = String(s.kelas || '') === studentFilterClass && isStudentActiveInClass(s);
      }
      
      let statusOk = true;
      const sStatus = String(s.status || 'Aktif');
      if (studentFilterStatus === 'Aktif') {
        statusOk = isStudentActiveInClass(s) && (sStatus === 'Aktif' || !s.status);
      } else if (studentFilterStatus === 'Tidak Aktif') {
        statusOk = !isStudentActiveInClass(s) || sStatus === 'Tidak Aktif' || sStatus === 'Mutasi' || sStatus === 'Mutasi Keluar';
      } else if (studentFilterStatus === 'Mutasi') {
        statusOk = !isStudentActiveInClass(s) || sStatus === 'Mutasi' || sStatus === 'Mutasi Keluar';
      } else if (studentFilterStatus !== 'SEMUA') {
        statusOk = sStatus === studentFilterStatus;
      }

      // Status Ayah & Ibu Filter (Masih Hidup, Meninggal, Cerai)
      const matchParentStatus = (statusValue: any, filter: string): boolean => {
        if (filter === 'SEMUA' || !filter) return true;
        const val = String(statusValue || '').trim().toLowerCase();
        if (filter === 'Masih Hidup') {
          if (!val) return true; // Default masukan orang tua adalah masih hidup jika belum diisi
          return val.includes('hidup') && !val.includes('cerai mati');
        }
        if (filter === 'Meninggal') {
          return val.includes('meninggal') || val.includes('wafat') || val.includes('mati') || val.includes('almarhum');
        }
        if (filter === 'Cerai') {
          return val.includes('cerai') || val.includes('pisah');
        }
        return val.includes(filter.toLowerCase());
      };

      const ayahStatusOk = matchParentStatus(s.statusAyah, studentFilterStatusAyah);
      const ibuStatusOk = matchParentStatus(s.statusIbu, studentFilterStatusIbu);
      
      return searchOk && ortuOk && classOk && statusOk && ayahStatusOk && ibuStatusOk;
    });

    const dedupeStudentsByNik = (list: SchoolStudent[]) => {
      const map = new Map<string, SchoolStudent>();
      (list || []).forEach(s => {
        if (!s) return;
        const key = getStudentUniqueKey(s);
        if (!map.has(key)) {
          map.set(key, s);
        } else {
          // If duplicate found, prioritize active student record
          const existing = map.get(key)!;
          const isExistingActive = isStudentActiveInClass(existing) && (existing.status === 'Aktif' || !existing.status);
          const isNewActive = isStudentActiveInClass(s) && (s.status === 'Aktif' || !s.status);
          if (!isExistingActive && isNewActive) {
            map.set(key, s);
          }
        }
      });
      return Array.from(map.values());
    };

    return dedupeStudentsByNik(filtered).sort((a, b) => {
      let valA = String(getStudentColumnValue(a, studentSortField) || '');
      let valB = String(getStudentColumnValue(b, studentSortField) || '');
      
      if (valA === '-' || valA === 'Belum Diatur') valA = '';
      if (valB === '-' || valB === 'Belum Diatur') valB = '';

      if (studentSortDirection === 'asc') {
        return valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' });
      }
      return valB.localeCompare(valA, undefined, { numeric: true, sensitivity: 'base' });
    });
  })();

  const totalFilteredCount = filteredAndSortedStudents.length;
  const studentItemsPerPage = 20;
  const studentTotalPages = Math.ceil(totalFilteredCount / studentItemsPerPage);
  const activeStudentPage = Math.max(1, Math.min(studentCurrentPage, studentTotalPages || 1));

  const handleExportSiswaExcel = () => {
    if (filteredAndSortedStudents.length === 0) {
      alert("Tidak ada data untuk diekspor");
      return;
    }

    const exportData = filteredAndSortedStudents.map((s: any, idx: number) => {
      return {
        'No': idx + 1,
        'NISN': sanitizeIdNumber(s.nisn) || '-',
        'NIS': sanitizeIdNumber(s.nis) || '-',
        'NIK': sanitizeIdNumber(s.nik) || '-',
        'Nama Lengkap': s.nama || '-',
        'Jenis Kelamin': s.gender || s.jenisKelamin || '-',
        'Tempat Lahir': s.tempatLahir || '-',
        'Tanggal Lahir': formatDateToDDMMYYYY(s.tanggalLahir),
        'Tanggal Masuk': formatDateToDDMMYYYY(s.tanggalMasuk),
        'Agama': s.agama || 'Islam',
        'Jumlah Saudara': s.saudara || '-',
        'Nomor KK': sanitizeIdNumber(s.noKK) || '-',
        'Status Keaktifan': s.status || 'Aktif',
        'Sekolah Asal': s.sekolahAsal || '-',
        'Alamat Lengkap': s.alamat || '-',
        'RT': s.rt || '-',
        'RW': s.rw || '-',
        'Dusun / Lingkungan': s.dusun || '-',
        'Desa / Kelurahan': s.kelurahan || '-',
        'Kecamatan': s.kecamatan || '-',
        'Kabupaten / Kota': s.kabupatenKota || '-',
        'Provinsi': s.provinsi || '-',
        'Jarak Rumah (km)': s.jarakRumah !== undefined ? s.jarakRumah : '-',
        'Nama Ayah': s.namaAyah || s.ortu || '-',
        'Status Ayah': s.statusAyah || '-',
        'NIK Ayah': sanitizeIdNumber(s.nikAyah) || '-',
        'Tempat Lahir Ayah': s.tlAyah || '-',
        'Pekerjaan Ayah': s.pekerjaanAyah || '-',
        'No HP / WA Ayah': sanitizeIdNumber(s.hpAyah) || '-',
        'Nama Ibu': s.namaIbu || '-',
        'Status Ibu': s.statusIbu || '-',
        'NIK Ibu': sanitizeIdNumber(s.nikIbu) || '-',
        'Tempat Lahir Ibu': s.tlIbu || '-',
        'Pekerjaan Ibu': s.pekerjaanIbu || '-',
        'No HP / WA Ibu': sanitizeIdNumber(s.hpIbu) || '-',
        'Nama Wali': s.ortu || s.namaAyah || s.namaIbu || '-',
        'No HP / WA Orang Tua (Utama)': sanitizeIdNumber(s.noHpOrangTua || s.noHp) || '-',
        'Jumlah Hafalan': s.jumlahHafalan || '-',
        'Nilai Rapor': s.nilaiRapor !== undefined ? s.nilaiRapor : '-',
        'Prestasi Akademik': s.prestasiAkademik || '-',
        'Prestasi Non-Akademik': s.prestasiNonAkademik || '-'
      };
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    
    // Auto adjust column widths for clean readability
    const colKeys = Object.keys(exportData[0] || {});
    ws['!cols'] = colKeys.map(key => {
      let maxLen = key.length;
      exportData.forEach((row: any) => {
        const valStr = String(row[key] || '');
        if (valStr.length > maxLen) {
          maxLen = Math.min(valStr.length, 50);
        }
      });
      return { wch: Math.max(maxLen + 3, 10) };
    });

    // Enforce string formatting on identifier cells so Excel never uses scientific notation (e.g. 3,31E+15) or alters date format
    const textColumns = ['NISN', 'NIS', 'NIK', 'Nomor KK', 'NIK Ayah', 'NIK Ibu', 'No HP / WA Ayah', 'No HP / WA Ibu', 'No HP / WA Orang Tua (Utama)', 'Tanggal Lahir', 'Tanggal Masuk'];
    const textIndices = textColumns.map(col => colKeys.indexOf(col)).filter(i => i !== -1);
    const range = XLSX.utils.decode_range(ws['!ref'] || 'A1:A1');
    for (let R = 1; R <= range.e.r; ++R) {
      for (const C of textIndices) {
        const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
        if (ws[cellRef]) {
          ws[cellRef].t = 's';
          ws[cellRef].z = '@';
        }
      }
    }

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Data Lengkap Siswa");
    XLSX.writeFile(wb, `Data_Lengkap_Siswa_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportSiswaPDF = () => {
    if (filteredAndSortedStudents.length === 0) {
      alert("Tidak ada data untuk diekspor");
      return;
    }

    const activeColIds = selectedStudentCols.filter(c => c !== 'foto');
    
    if (activeColIds.length === 0) {
      alert("Silakan pilih minimal 1 kolom data di menu 'Pilih Kolom' untuk diekspor ke PDF");
      return;
    }

    const orientation = activeColIds.length > 5 ? 'landscape' : 'portrait';
    const doc = new jsPDF({ orientation });

    const tableColumn = ["No", ...activeColIds.map(c => {
      const found = ALL_STUDENT_TABLE_COLUMNS.find(col => col.id === c);
      return found ? found.label : c;
    })];

    const tableRows = filteredAndSortedStudents.map((s, idx) => [
      idx + 1,
      ...activeColIds.map(c => getStudentColumnValue(s, c))
    ]);

    doc.setFontSize(15);
    doc.setFont("helvetica", "bold");
    doc.text("DAFTAR SANTRI AL-IHSAN WATTAQWA", 14, 18);
    
    doc.setFontSize(8.5);
    doc.setFont("helvetica", "normal");
    doc.text(`Tahun Ajaran: ${tahunAjaranAktif} | Semester: ${semesterAktif} | Total Santri: ${filteredAndSortedStudents.length}`, 14, 25);
    doc.text(`Tanggal Cetak: ${new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })} | Kolom Ditampilkan: ${activeColIds.length} Kolom`, 14, 30);

    const fontSize = activeColIds.length > 10 ? 6 : (activeColIds.length > 6 ? 7 : 8);
    const cellPadding = activeColIds.length > 10 ? 1.5 : 2;

    autoTable(doc, {
      head: [tableColumn],
      body: tableRows,
      startY: 35,
      theme: 'grid',
      styles: { 
        fontSize: fontSize, 
        cellPadding: cellPadding,
        overflow: 'linebreak',
        textColor: [30, 41, 59]
      },
      headStyles: { 
        fillColor: [15, 23, 42], 
        textColor: 255, 
        fontStyle: 'bold',
        halign: 'center',
        fontSize: fontSize
      },
      alternateRowStyles: { 
        fillColor: [248, 250, 252] 
      },
      columnStyles: {
        0: { halign: 'center', cellWidth: 10 }
      }
    });

    doc.save(`Daftar_Siswa_${new Date().toISOString().split('T')[0]}.pdf`);
  };

  const handleExportTahfidzExcel = () => {
    const filtered = tahfidzRecords.filter(r => {
      const matchStudent = tahfidzRekapStudentId === 'Semua' || r.siswaId === tahfidzRekapStudentId;
      const recordDate = r.tanggalMulai || (r as any).tanggal;
      const matchStart = !tahfidzRekapStartDate || (recordDate && recordDate >= tahfidzRekapStartDate);
      const matchEnd = !tahfidzRekapEndDate || (recordDate && recordDate <= tahfidzRekapEndDate);
      return matchStudent && matchStart && matchEnd;
    }).sort((a, b) => String(b.tanggalMulai || (b as any).tanggal || '').localeCompare(String(a.tanggalMulai || (a as any).tanggal || '')));

    if (filtered.length === 0) {
      alert('Tidak ada data setoran hafalan untuk diekspor ke Excel.');
      return;
    }

    const exportData = filtered.map((r, idx) => {
      const s = students.find(x => x.id === r.siswaId);
      const u = ustadzList.find(x => x.id === r.ustadzPenyimakId);
      return {
        'No': idx + 1,
        'Nama Santri': (s?.nama || r.siswaId).toUpperCase(),
        'NISN': s?.nisn || '-',
        'Tanggal Mulai': r.tanggalMulai || (r as any).tanggal || '-',
        'Tanggal Selesai': r.tanggalSelesai || (r as any).tanggal || '-',
        'Juz': `Juz ${r.noJuz}`,
        'Jenis Setoran': r.jenisSetoran,
        'Jumlah Halaman': `${r.jumlahHalaman} Hal`,
        'Tajwid': r.nilaiTajwid || '-',
        'Fashohah': r.nilaiFashohah || '-',
        'Kelancaran': r.nilaiKelancaran || '-',
        'Ustadz Penyimak': u?.nama || '-',
        'Catatan': r.catatan || '-'
      };
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Rekap Tahfidz');
    XLSX.writeFile(wb, `Rekap_Tahfidz_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const handleExportTahfidzPDF = () => {
    const filtered = tahfidzRecords.filter(r => {
      const matchStudent = tahfidzRekapStudentId === 'Semua' || r.siswaId === tahfidzRekapStudentId;
      const recordDate = r.tanggalMulai || (r as any).tanggal;
      const matchStart = !tahfidzRekapStartDate || (recordDate && recordDate >= tahfidzRekapStartDate);
      const matchEnd = !tahfidzRekapEndDate || (recordDate && recordDate <= tahfidzRekapEndDate);
      return matchStudent && matchStart && matchEnd;
    }).sort((a, b) => String(b.tanggalMulai || (b as any).tanggal || '').localeCompare(String(a.tanggalMulai || (a as any).tanggal || '')));

    if (filtered.length === 0) {
      alert('Tidak ada data setoran hafalan untuk dicetak ke PDF.');
      return;
    }

    const doc = new jsPDF({ orientation: 'landscape' });
    doc.setFontSize(14);
    doc.text('Laporan Rekap Setoran Hafalan Santri (Tahfidz)', 14, 15);
    doc.setFontSize(9);
    doc.text(`Dicetak pada: ${new Date().toLocaleDateString('id-ID')} | Filter Santri: ${tahfidzRekapStudentId === 'Semua' ? 'Semua Santri' : (students.find(s => s.id === tahfidzRekapStudentId)?.nama || tahfidzRekapStudentId)}`, 14, 22);

    const tableRows = filtered.map((r, idx) => {
      const s = students.find(x => x.id === r.siswaId);
      const u = ustadzList.find(x => x.id === r.ustadzPenyimakId);
      return [
        idx + 1,
        (s?.nama || r.siswaId).toUpperCase(),
        `${r.tanggalMulai || (r as any).tanggal || '-'} s/d ${r.tanggalSelesai || (r as any).tanggal || '-'}`,
        `Juz ${r.noJuz}`,
        `${r.jenisSetoran} (${r.jumlahHalaman} Hal)`,
        `T:${r.nilaiTajwid || '-'} F:${r.nilaiFashohah || '-'} K:${r.nilaiKelancaran || '-'}`,
        u?.nama || '-'
      ];
    });

    autoTable(doc, {
      startY: 26,
      head: [['No', 'Nama Santri', 'Rentang Tanggal', 'Juz', 'Setoran', 'Kualitas (T/F/K)', 'Ustadz Penyimak']],
      body: tableRows,
      theme: 'grid',
      headStyles: { fillColor: [15, 23, 42], textColor: [255, 255, 255], fontStyle: 'bold', fontSize: 9 },
      bodyStyles: { fontSize: 8 }
    });

    doc.save(`Rekap_Tahfidz_${new Date().toISOString().split('T')[0]}.pdf`);
  };

  const paginatedStudents = filteredAndSortedStudents.slice(
    (activeStudentPage - 1) * studentItemsPerPage,
    activeStudentPage * studentItemsPerPage
  );

