                                    const matchEnd = !rekapTeacherEndDate || h.tanggal <= rekapTeacherEndDate;
                                    const matchYear = h.academicYear === tahunAjaranAktif;
                                    return matchTeacher && matchStart && matchEnd && matchYear;
