                                  const hadirHari = tRecs.filter(x => x.status === 'Hadir').length;
                                  const hadirHisoh = tRecs.filter(x => x.status === 'Hadir').reduce((acc, curr) => acc + (curr.hisoh || 0), 0);
                                  const izinHari = tRecs.filter(x => x.status === 'Izin').length;
