                                  const totalHari = hadirHari + izinHari + sakitHari + alpaHari;
                                  const totalHisoh = tRecs.reduce((acc, curr) => acc + (curr.hisoh || 0), 0);
                                  
                                  const hadirHariPct = totalHari > 0 ? ((hadirHari / totalHari) * 100).toFixed(1) + '%' : '0%';
                                  const hadirHisohPct = totalHisoh > 0 ? ((hadirHisoh / totalHisoh) * 100).toFixed(1) + '%' : '0%';
                                  const izinHariPct = totalHari > 0 ? ((izinHari / totalHari) * 100).toFixed(1) + '%' : '0%';
